 if(!j.nodes?.length||!j.meshes?.length)throw Error("Missing geometry");
 const names=new Set(j.nodes.map(x=>x.name));
 for(const a of ["ANCHOR_Entrance","ANCHOR_Sign","ANCHOR_Roof","COLLIDER_Footprint"])if(!names.has(a))throw Error("Missing "+a);
 const bounds=j.accessors.filter(a=>a.type==="VEC3"&&Array.isArray(a.min));
 for(const a of bounds)if(a.min.some((x,i)=>x>a.max[i]||!Number.isFinite(x)))throw Error("Bad bounds");
